window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[77]={"id":"077","numero":77,"titre":"Addiction aux médicaments psychotropes (benzodiazépines)","objectifs":[{"id":"77-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’addiction aux benzodiazépines et apparentés","contenu":"<div class=\"notion-course\"><p><span>Les</span> <span>psychotropes</span> sont l'ensemble des substances chimiques, naturelles ou artificielles, ayant un tropisme « psychologique » : elles modifient l'<span>activité mentale</span> (définition de Delay et Deniker). Les <span>benzodiazépines (<span class=\"nc-pink_bg\">BZD</span>) et apparentés</span> constituent la principale classe d'<span><span class=\"nc-pink_bg\">anxiolytiques</span></span> et d'<span><span class=\"nc-pink_bg\">hypnotiques</span></span>.</p>\n      <p>Sur le plan pharmacologique, <span>les</span> BZD sont des <span>modulateurs allostériques positifs <span class=\"nc-yellow_bg\">des récepteurs</span> GABA-A</span> : elles <span class=\"nc-green_bg\">facilitent la</span> <span><span class=\"nc-green_bg nc-bold\">transmission GABAergique</span> inhibitrice</span> et diminuent l'hyperexcitabilité neuronale liée à l'<span class=\"nc-blue_bg\">anxiété</span>. Cette action expose à deux conséquences propres aux BZD :</p>\n      <ul>\n        <li>une <span><span class=\"nc-red_bg\">tolérance pharmacologique</span></span> rapide → <strong><span class=\"nc-red nc-bold\">perte d'efficacité</span></strong> du traitement à dose constante ;</li>\n        <li>un <span>phénomène de sevrage</span> à l'arrêt si le traitement a été prolongé.</li>\n      </ul>\n      <p>L'<span>addiction aux benzodiazépines</span> est un <span>mésusage par syndrome de <span class=\"nc-red_bg\">dépendance</span></span> : impossibilité répétée de contrôler la consommation et poursuite malgré la connaissance des conséquences négatives. Elle associe trois registres de symptômes :</p>\n      <table>\n        <thead><tr><th>Registre</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><span>Comportemental</span></td><td><span>Perte de contrôle</span> progressive ; <span>craving</span> (envie irrépressible) ; <span>envahissement</span> de la vie quotidienne au détriment des autres activités</td></tr>\n          <tr><td><span>Pharmacologique</span></td><td><span>Tolérance</span> (besoin d'augmenter <span>les</span> doses) ; <span><span class=\"nc-red nc-bold\">syndrome de sevrage</span></span> à l'arrêt — ni systématiques ni nécessaires au diagnostic</td></tr>\n          <tr><td><span>Répercussions</span></td><td>Conséquences <strong>sociales</strong> (<span>isolement</span>, marginalisation) et/ou <strong>médicales</strong> durables et significatives</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> <span>Les</span> <span class=\"nc-pink_bg\">BZD</span> ont aussi un <span><span class=\"nc-red_bg\">effet désinhibiteur</span></span> pouvant expliquer des <strong><span class=\"nc-red nc-bold\">troubles du comportement « paradoxaux »</span></strong> (<span class=\"nc-red nc-bold\">agitation</span>, <span class=\"nc-red nc-bold\">agressivité</span>), favorisés par l'<span>alcool</span> et fréquents chez l'adolescent.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes · 76 — Addiction à l'<span>alcool</span></em></p><div class=\"callout\"><p><span class=\"nc-red_bg\">Dépendance</span> physique et trouble de l’usage ne sont pas synonymes. Tolérance et sevrage peuvent survenir sous prescription correcte sans perte de contrôle ni addiction.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181d98572d394bc93953c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Psychotropes (74, 77)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418114bbc9f2338b5b6b96?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Benzodiazépines</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details><details data-lisa-review=\"20261014\"><summary>Situations de départ LiSA vérifiées</summary><p>Attendus consultés sur LiSA 2026 le 14 octobre 2026, reformulés pour la révision.</p><ul><li><a href=\"https://livret.uness.fr/lisa/2026/Prescrire_un_hypnotique/anxiolytique_SDD-256\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 256 · Prescrire un hypnotique/anxiolytique</a><ul><li>Préciser le trouble du sommeil, rechercher une apnée et privilégier les approches non médicamenteuses.</li><li>Adapter prescription et déprescription au terrain ; expliquer dépendance et sevrage, repérer mésusage et choisir l’ordonnance adaptée.</li></ul></li><li><a href=\"https://livret.uness.fr/lisa/2026/Prise_volontaire_ou_involontaire_d%27un_toxique_ou_d%27un_m%C3%A9dicament_potentiellement_toxique_SDD-340\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 340 · Prise d’un toxique ou médicament potentiellement toxique</a><ul><li>Dater et quantifier l’exposition, reconnaître les toxidromes, évaluer la gravité et considérer un antidote adapté.</li><li>Organiser surveillance et orientation, évaluer intention suicidaire ou maltraitance et solliciter le centre antipoison selon la situation.</li></ul></li><li><a href=\"https://livret.uness.fr/lisa/2026/Premi%C3%A8re_consultation_d%27addictologie_SDD-292\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 292 · Première consultation d’addictologie</a><ul><li>Caractériser usage nocif, dépendance ou addiction comportementale selon la classification utilisée ; rechercher sevrage, complications et comorbidités.</li><li>Évaluer les conséquences familiales, sociales et professionnelles, fixer des objectifs partagés et orienter ou proposer une substitution selon indication.</li></ul></li><li><a href=\"https://livret.uness.fr/lisa/2026/Consultation_de_suivi_addictologie_SDD-293\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 293 · Consultation de suivi addictologie</a><ul><li>Rechercher manque, nouveaux symptômes, complications et comorbidités ; apprécier efficacité, tolérance et qualité de vie.</li><li>Adapter prescription et accompagnement social ; la valorisation du stage inclut psychothérapie, entretien motivationnel et soutien des proches avec respect de la confidentialité.</li></ul></li></ul><p>Les liens ciblent les compétences pertinentes pour cet item ; ils ne signifient pas que la fiche couvre à elle seule toute la situation de départ.</p></details>","frequence":0},{"id":"77-2","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer une intoxication aiguë aux benzodiazépines","contenu":"<div class=\"notion-course\"><h4>Toxidrome et urgence</h4><ul><li>Somnolence, <span class=\"nc-blue_bg\">dysarthrie</span>, ataxie, hypotonie et parfois <span class=\"nc-yellow_bg\">coma calme</span> ; pupilles généralement normales et absence de signe focal attendue.</li><li><span class=\"nc-red nc-bold\">Dépression respiratoire</span> surtout en association avec opioïdes, alcool ou autres <span class=\"nc-green_bg\">sédatifs</span>. Ne pas attribuer un coma à une BZD sans rechercher hypoglycémie, traumatisme, cause neurologique et autres toxiques.</li><li>Priorité : voies aériennes, ventilation, constantes, glycémie et surveillance ; appeler réanimation et centre antipoison selon gravité.</li></ul><h4><span class=\"nc-pink nc-bold\">Flumazénil</span> : indication sélectionnée</h4><p><span class=\"nc-yellow_bg nc-bold\">Antagoniste</span> du site benzodiazépine du récepteur GABA-A, utilisable par titration IV en milieu monitoré après évaluation du rapport bénéfice-risque. Il ne remplace pas la ventilation. Son effet peut être plus court que celui du toxique : <span class=\"nc-orange_bg\">risque de</span> resédation.</p><div class=\"callout\"><p>Éviter son emploi systématique dans un coma toxique indéterminé, une intoxication mixte proconvulsivante (notamment tricycliques), une <span class=\"nc-red_bg\">dépendance</span> aux BZD ou lorsque celles-ci contrôlent une <span class=\"nc-red_bg nc-bold\">épilepsie</span> : <span class=\"nc-orange_bg\">risque de</span> sevrage et de convulsions. Le protocole dépend du contexte et du RCP ; aucune perfusion automatique.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181d98572d394bc93953c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Psychotropes (74, 77)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418114bbc9f2338b5b6b96?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Benzodiazépines</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"77-3","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer un mésusage : usage à risque, nocif et dépendance","contenu":"<div class=\"notion-course\"><h4>Usage, <span class=\"nc-red_bg\">dépendance</span> et contexte de prescription</h4><table><thead><tr><th>Situation</th><th>Repère</th></tr></thead><tbody><tr><td>Usage thérapeutique</td><td>Indication, dose, durée et surveillance adaptées ; risques possibles malgré un usage correct.</td></tr><tr><td>Usage à risque</td><td>Exposition dangereuse sans dommage encore établi : doses élevées, prolongation injustifiée, associations, conduite ou prises non prescrites.</td></tr><tr><td>Usage nocif (CIM-10)</td><td>Dommage somatique ou psychique avéré, sans critères de <span class=\"nc-red_bg\">dépendance</span>.</td></tr><tr><td><span class=\"nc-red_bg\">Dépendance</span> CIM-10</td><td>Au moins trois manifestations réunies au cours de l’année : craving, perte de contrôle, sevrage, tolérance, réduction des autres intérêts, poursuite malgré dommages.</td></tr></tbody></table><p>Le DSM-5 regroupe les troubles de l’usage des <span class=\"nc-green_bg\">sédatifs</span>, <span class=\"nc-pink_bg\">hypnotiques</span> ou <span class=\"nc-pink_bg\">anxiolytiques</span> : au moins deux critères en douze <span class=\"nc-pink_bg\">mois</span>. La tolérance et le sevrage lors d’un traitement exclusivement sous surveillance médicale appropriée ne suffisent pas au diagnostic. Ne pas confondre les classifications.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181d98572d394bc93953c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Psychotropes (74, 77)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418114bbc9f2338b5b6b96?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Benzodiazépines</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":1},{"id":"77-4","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer un syndrome de sevrage et complications du sevrage","contenu":"<div class=\"notion-course\"><h4>Sevrage, rebond ou rechute ?</h4><table><thead><tr><th>Phénomène</th><th>Description</th></tr></thead><tbody><tr><td>Sevrage</td><td>Symptômes nouveaux après baisse ou arrêt : <span class=\"nc-blue_bg\">anxiété</span>, <span class=\"nc-blue_bg\">insomnie</span>, <span class=\"nc-red nc-bold\">tremblements</span>, hypersensibilité, troubles perceptifs ; formes graves : <span class=\"nc-yellow_bg\">confusion</span>, délirium, <span class=\"nc-red nc-bold\">convulsions</span>.</td></tr><tr><td>Rebond</td><td>Retour transitoire majoré du symptôme initial.</td></tr><tr><td>Rechute</td><td>Réapparition durable du trouble initial.</td></tr></tbody></table><ul><li>Délai et durée dépendent notamment de la demi-vie, de la dose et de l’ancienneté ; un début retardé est possible.</li><li>Risques accrus : arrêt rapide, doses fortes, demi-vie courte, antécédent de sevrage compliqué, comorbidités et autres consommations.</li><li><span class=\"nc-yellow_bg\">Confusion</span> ou convulsion : urgence hospitalière ; ces signes ne sont pas spécifiques aux BZD.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181d98572d394bc93953c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Psychotropes (74, 77)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418114bbc9f2338b5b6b96?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Benzodiazépines</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2038262/fr/arret-des-benzodiazepines-et-medicaments-apparentes-demarche-du-medecin-traitant-en-ambulatoire\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Arrêt des benzodiazépines, démarche en ambulatoire</a></li></ul><p></p></details>","frequence":1},{"id":"77-5","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer les comorbidités psychiatriques et addictives","contenu":"<div class=\"notion-course\"><h4>Évaluation associée</h4><ul><li>Rechercher trouble anxieux, dépression, risque suicidaire, trouble du sommeil et indication initiale encore active.</li><li>Questionner alcool, opioïdes et autres psychotropes, automédication, ordonnances multiples et mésusage.</li><li>Évaluer cognition, chutes, conduite, autonomie, isolement et soutien disponible.</li><li>Distinguer trouble sous-jacent, effet indésirable, rebond et sevrage ; traiter les comorbidités en parallèle.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181d98572d394bc93953c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Psychotropes (74, 77)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418114bbc9f2338b5b6b96?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Benzodiazépines</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"77-6","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie de la dépendance aux benzodiazépines et apparentés","contenu":"<div class=\"notion-course\"><h4>Des prescriptions fréquentes, sans équivalence avec une addiction</h4><p>L’ANSM rapporte plus de 9 millions d’utilisateurs en France en 2024 et situe la France au deuxième rang européen. Utilisateur, traitement prolongé, <span class=\"nc-red_bg\">dépendance</span> physique et trouble de l’usage sont des dénominateurs différents.</p><p>Les anciennes proportions du cours issues notamment de 2012–2015 ne décrivent pas la prévalence actuelle de l’addiction. La prévention cible les prescriptions longues, les <span class=\"nc-green_bg\">personnes âgées</span> et les associations de dépresseurs du système nerveux central.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181d98572d394bc93953c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Psychotropes (74, 77)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418114bbc9f2338b5b6b96?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Benzodiazépines</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://ansm.sante.fr/page/les-medicaments-et-moi-bub\" target=\"_blank\" rel=\"noopener noreferrer\">ANSM · Bon usage des benzodiazépines, données 2024</a></li></ul><p></p></details>","frequence":0},{"id":"77-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de prévention de la pharmacodépendance","contenu":"<div class=\"notion-course\"><h4>Prévoir la sortie dès l’entrée</h4><ul><li>Indication précise, plus faible dose efficace et durée la plus courte possible ; date de réévaluation et information sur l’<span class=\"nc-green_bg nc-bold\">arrêt</span>.</li><li><span class=\"nc-blue_bg\">Anxiété</span> : habituellement 8–12 <span class=\"nc-pink_bg\">semaines</span> au maximum, diminution comprise ; <span class=\"nc-blue_bg\">insomnie</span> : jusqu’à 4 <span class=\"nc-pink_bg\">semaines</span>, avec limites plus courtes selon le produit.</li><li>Éviter doublons, alcool et associations sédatives ; informer sur conduite, chutes, <span class=\"nc-blue_bg nc-bold\">mémoire</span> et <span class=\"nc-red_bg\">dépendance</span>.</li><li>Chez le sujet âgé : éviter autant que possible, réduire la dose initiale selon le produit, la fragilité et les fonctions d’organe.</li><li><span class=\"nc-pink nc-bold\">Zolpidem</span> : <span class=\"nc-yellow_bg\">ordonnance sécurisée</span>. Ces durées concernent les indications <span class=\"nc-pink_bg\">anxiolytiques</span>/<span class=\"nc-pink_bg\">hypnotiques</span> et ne s’appliquent pas indistinctement à toute <span class=\"nc-red_bg nc-bold\">épilepsie</span>.</li><li>Privilégier les soins du trouble causal et les approches non médicamenteuses, notamment TCC de l’<span class=\"nc-blue_bg\">insomnie</span>.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181d98572d394bc93953c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Psychotropes (74, 77)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418114bbc9f2338b5b6b96?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Benzodiazépines</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2863043/fr/quelle-place-pour-les-benzodiazepines-dans-l-anxiete\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Benzodiazépines dans l’anxiété</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2015058/fr/quelle-place-pour-les-benzodiazepines-dans-l-insomnie\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Benzodiazépines dans l’insomnie</a></li></ul><p></p></details>","frequence":0},{"id":"77-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de réduction des dommages et des risques","contenu":"<div class=\"notion-course\"><h4>Réduire les dommages avec le patient</h4><ul><li>Décision partagée et maintien du lien ; une baisse stabilisée constitue déjà un résultat utile.</li><li>Prescripteur et pharmacie coordonnés, délivrance fractionnée si pertinente, revue de tous les traitements.</li><li>Réduire les associations alcool/opioïdes et les situations de conduite ou chute à risque.</li><li>Ne pas imposer une réduction rapide pour respecter artificiellement une durée administrative ; adapter le rythme à la tolérance.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181d98572d394bc93953c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Psychotropes (74, 77)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418114bbc9f2338b5b6b96?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Benzodiazépines</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":2},{"id":"77-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de la prise en charge du sevrage","contenu":"<div class=\"notion-course\"><h4>Plan de diminution individualisé</h4><ol><li>Évaluer dose, durée, tentatives antérieures, <span class=\"nc-red_bg\">dépendance</span>, risques de convulsions et contexte psychosocial.</li><li>Choisir ambulatoire si situation stable ; avis spécialisé ou hospitalisation si <span class=\"nc-red nc-bold\">doses très élevées</span>, sevrage compliqué antérieur, comorbidité grave ou polydépendance instable.</li><li>Diminuer par paliers sur plusieurs <span class=\"nc-pink_bg\">semaines</span> à plusieurs <span class=\"nc-pink_bg\">mois</span>, parfois davantage ; il n’existe pas de pourcentage universel imposé.</li><li>Si symptômes gênants : réévaluer, ralentir ou stabiliser le palier ; urgence si <span class=\"nc-red nc-bold\">convulsions</span> ou <span class=\"nc-yellow_bg\">confusion</span>.</li><li>Traiter <span class=\"nc-blue_bg\">anxiété</span>/<span class=\"nc-blue_bg\">insomnie</span>, proposer soutien ou TCC, organiser les consultations et le suivi après l’<span class=\"nc-green_bg nc-bold\">arrêt</span>.</li></ol><div class=\"callout\"><p>Ne pas arrêter brutalement une consommation <span class=\"nc-red nc-bold\">prolongée</span>. Une substitution par une molécule à demi-vie longue peut être discutée dans certains cas ; elle n’est pas obligatoire et exige une conversion prudente.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181d98572d394bc93953c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Psychotropes (74, 77)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418114bbc9f2338b5b6b96?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Benzodiazépines</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2038262/fr/arret-des-benzodiazepines-et-medicaments-apparentes-demarche-du-medecin-traitant-en-ambulatoire\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Arrêt des benzodiazépines, démarche en ambulatoire</a></li></ul><p></p></details>","frequence":1}],"astuces":[{"type":"piege","titre":"Arrêt","contenu":"<div class=\"notion-course\"><p>Une consommation <span class=\"nc-red nc-bold\">prolongée</span> impose un arrêt <span class=\"nc-green_bg nc-bold\">progressif</span> et accompagné.</p></div>"},{"type":"piege","titre":"Antidote","contenu":"<div class=\"notion-course\"><p><span class=\"nc-pink nc-bold\">Flumazénil</span> : indication sélectionnée, pas de réflexe devant tout coma.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Distinguer intoxication, sevrage, rebond et trouble sous-jacent.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Réduire les risques, convenir des objectifs et adapter la diminution.</li></ul></div>","Examens complémentaires":"<div class=\"notion-course\"><ul><li>Les examens sont orientés par la gravité et les diagnostics différentiels.</li></ul></div>"},"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Somnolence, ataxie ou coma après exposition ?","detail":"<ul><li>Évaluer conscience, respiration, circulation, température et glycémie.</li><li>Chercher opioïdes, alcool, autres psychotropes et geste suicidaire.</li></ul>","branches":[{"label":"Défaillance / coma","to":"urgence"},{"label":"Patient stable","to":"surveillance"}]},{"id":"urgence","kind":"decision","label":"Support vital et avis toxicologique/réanimation","detail":"<ul><li>Protéger voies aériennes et ventilation selon état ; ne pas attendre le dosage.</li></ul>","branches":[{"label":"Discussion d’un antidote","to":"antidote"}]},{"id":"antidote","kind":"decision","label":"Flumazénil : bénéfice et contre-indications évalués ?","detail":"<ul><li>Pas d’antidote systématique du coma ; risque de convulsions et sevrage.</li><li>Usage chronique, épilepsie et intoxication mixte proconvulsivante limitent son emploi.</li></ul>","branches":[{"label":"Indication retenue par équipe compétente","to":"selection"},{"label":"Risque excessif / incertitude","to":"support"}]},{"id":"selection","kind":"urgent","label":"Administration titrée avec surveillance spécialisée","detail":"<ul><li>Risque de resédation ; maintenir moyens de réanimation et observation adaptée.</li></ul>","branches":[]},{"id":"support","kind":"urgent","label":"Poursuivre les soins de support et l’évaluation","detail":"<ul><li>Rechercher autre cause ; réévaluer régulièrement la respiration.</li></ul>","branches":[]},{"id":"surveillance","kind":"finish","label":"Observer selon produit, dose, terrain et associations","detail":"<ul><li>Évaluer intentionnalité, prévention des récidives et suivi.</li><li>Ne pas conclure à une intoxication bénigne sur le seul nom de la molécule.</li></ul>","branches":[]}]},"cards":[{"i":"073af8b42c59","n":77,"o":"77-1","u":"Définition","t":"Connaître la définition de l’addiction aux benzodiazépines et apparentés","q":"Quel est le mécanisme d'action pharmacologique des benzodiazépines (BZD) ?","a":"<div class=\"notion-course\"><p>Modulateurs allostériques positifs de GABA-A : elles renforcent l’effet inhibiteur du GABA, plutôt que d’être des agonistes directs du récepteur.</p></div>"},{"i":"2d1a7eacea19","n":77,"o":"77-1","u":"Définition","t":"Connaître la définition de l’addiction aux benzodiazépines et apparentés","q":"Comment l'addiction aux benzodiazépines est-elle définie ?","a":"<div class=\"notion-course\"><p>L'addiction aux benzodiazépines est un <strong>mésusage par syndrome de <span class=\"nc-red_bg\">dépendance</span></strong>. Elle se caractérise par une <strong>impossibilité répétée de contrôler la consommation</strong> et sa poursuite malgré la connaissance de ses conséquences négatives.</p></div>"},{"i":"349fbb0bb404","n":77,"o":"77-1","u":"Définition","t":"Connaître la définition de l’addiction aux benzodiazépines et apparentés","q":"Quelles sont les répercussions significatives de l'addiction aux benzodiazépines ?","a":"<div class=\"notion-course\"><p>Les répercussions de l'addiction aux benzodiazépines sont des <strong>conséquences sociales</strong> (comme l'isolement, la marginalisation) et/ou des <strong>conséquences médicales</strong> durables et significatives.</p></div>"},{"i":"470583bf6346","n":77,"o":"77-1","u":"Définition","t":"Connaître la définition de l’addiction aux benzodiazépines et apparentés","q":"Quelles sont les manifestations comportementales de l'addiction aux benzodiazépines ?","a":"<div class=\"notion-course\"><ul><li>Une <strong>perte de contrôle progressive</strong> de la consommation.</li><li>Le <strong>craving</strong> (envie irrépressible) du produit.</li><li>Un envahissement de la vie quotidienne par la consommation, au détriment des autres activités.</li></ul></div>"},{"i":"561788a270e1","n":77,"o":"77-1","u":"Définition","t":"Connaître la définition de l’addiction aux benzodiazépines et apparentés","q":"Qu'est-ce qu'un psychotrope selon la définition de Delay et Deniker ?","a":"<div class=\"notion-course\"><p>Un psychotrope est une substance chimique, d'origine naturelle ou artificielle, qui agit sur l'activité mentale en ayant un tropisme « psychologique ».</p></div>"},{"i":"bdc8a7113ff7","n":77,"o":"77-1","u":"Définition","t":"Connaître la définition de l’addiction aux benzodiazépines et apparentés","q":"Quelles sont les manifestations pharmacologiques pouvant être associées à l'addiction aux benzodiazépines ?","a":"<div class=\"notion-course\"><ul><li>La <strong>tolérance</strong>, nécessitant d'augmenter les doses pour obtenir le même effet.</li><li>Le <strong><span class=\"nc-red nc-bold\">syndrome de sevrage</span></strong> à l'arrêt du traitement, si celui-ci a été prolongé.</li></ul><p>Il est important de noter que ces manifestations ne sont <strong>ni systématiques ni nécessaires</strong> au diagnostic d'addiction.</p></div>"},{"i":"d5bb4ad94bbb","n":77,"o":"77-1","u":"Définition","t":"Connaître la définition de l’addiction aux benzodiazépines et apparentés","q":"Quel effet paradoxal des benzodiazépines peut expliquer des troubles du comportement, notamment chez l'adolescent ?","a":"<div class=\"notion-course\"><p>Les benzodiazépines peuvent avoir un <strong><span class=\"nc-red_bg\">effet désinhibiteur</span></strong>, expliquant des troubles du comportement dits « paradoxaux » tels que l'<strong><span class=\"nc-red nc-bold\">agitation</span> ou l'<span class=\"nc-red nc-bold\">agressivité</span></strong>. Cet effet est favorisé par l'alcool et est plus fréquent chez l'adolescent.</p></div>"},{"i":"1ad2e3608109","n":77,"o":"77-2","u":"Diagnostic positif","t":"Savoir diagnostiquer une intoxication aiguë aux benzodiazépines","q":"Quel est l'antidote spécifique de l'intoxication aux benzodiazépines et comment est-il administré ?","a":"<div class=\"notion-course\"><p><span class=\"nc-pink nc-bold\">Flumazénil</span>, <span class=\"nc-yellow_bg nc-bold\">antagoniste</span> du site benzodiazépine. Titration IV monitorée selon indication et RCP, uniquement après analyse des contre-indications ; surveiller la resédation. La ventilation reste prioritaire.</p></div>"},{"i":"26c249389f27","n":77,"o":"77-2","u":"Diagnostic positif","t":"Savoir diagnostiquer une intoxication aiguë aux benzodiazépines","q":"Quelles sont les contre-indications majeures à l'utilisation du flumazénil en cas d'intoxication aiguë aux benzodiazépines ?","a":"<div class=\"notion-course\"><p>Intoxication indéterminée ou mixte proconvulsivante (tricycliques), <span class=\"nc-red_bg\">dépendance</span> aux BZD, ou BZD nécessaires au contrôle d’une <span class=\"nc-red_bg nc-bold\">épilepsie</span> : <span class=\"nc-orange_bg\">risque de</span> convulsions/sevrage. Pas d’utilisation systématique.</p></div>"},{"i":"6b242e27abf2","n":77,"o":"77-2","u":"Diagnostic positif","t":"Savoir diagnostiquer une intoxication aiguë aux benzodiazépines","q":"Dans quel contexte clinique suspecter une intoxication aiguë aux benzodiazépines ?","a":"<div class=\"notion-course\"><p>L'intoxication aiguë aux benzodiazépines (BZD) survient le plus souvent dans un contexte d'<strong>intoxication volontaire</strong> (tentative de suicide) ou de surdosage, parfois associée à d'autres dépresseurs du SNC.</p></div>"},{"i":"ab43e34ebc30","n":77,"o":"77-2","u":"Diagnostic positif","t":"Savoir diagnostiquer une intoxication aiguë aux benzodiazépines","q":"Quels sont les signes cliniques négatifs (discriminants) d'une intoxication aiguë aux benzodiazépines, permettant de l'orienter face à d'autres toxidromes ?","a":"<div class=\"notion-course\"><ul><li><strong>Pupilles normales</strong>.</li><li><strong>Pas de signe de localisation</strong>.</li><li><strong>Absence de <span class=\"nc-blue nc-bold\">mydriase</span></strong> ni de signes végétatifs marqués.</li></ul></div>"},{"i":"b9281f44128e","n":77,"o":"77-2","u":"Diagnostic positif","t":"Savoir diagnostiquer une intoxication aiguë aux benzodiazépines","q":"Quel est le risque vital principal de l'intoxication aiguë aux benzodiazépines et sa prise en charge immédiate ?","a":"<div class=\"notion-course\"><p>Le risque vital principal est l'<strong>asphyxie par obstruction des voies aériennes supérieures</strong>, due à l'association d'un coma et d'une <span class=\"nc-yellow_bg\">myorelaxation</span>. Tout trouble important de la <span class=\"nc-red_bg\">vigilance</span> impose une <strong>prise en charge en urgence</strong> (protection des voies aériennes).</p></div>"},{"i":"beef4a4db6ff","n":77,"o":"77-2","u":"Diagnostic positif","t":"Savoir diagnostiquer une intoxication aiguë aux benzodiazépines","q":"Quels sont les signes cliniques positifs d'une intoxication aiguë aux benzodiazépines ?","a":"<div class=\"notion-course\"><ul><li><strong><span class=\"nc-red_bg\">Vigilance</span></strong> : somnolence jusqu'au <strong><span class=\"nc-yellow_bg\">coma calme</span></strong>, troubles mnésiques.</li><li><strong>Tonus</strong> : <strong><span class=\"nc-yellow_bg\">myorelaxation</span></strong>, hypotonie, <strong>ROT diminués ou abolis</strong> (<span class=\"nc-blue_bg\">hyporéflexie</span>).</li><li><strong>Autres</strong> : <span class=\"nc-blue_bg\">dysarthrie</span>, ataxie, <span class=\"nc-red nc-bold\">bradypnée</span> et <strong><span class=\"nc-red nc-bold\">dépression respiratoire</span></strong>.</li></ul></div>"},{"i":"3703992692a9","n":77,"o":"77-3","u":"Diagnostic positif","t":"Savoir diagnostiquer un mésusage : usage à risque, nocif et dépendance","q":"Comment est défini le mésusage des médicaments psychotropes, notamment les benzodiazépines, dans le contexte de l'addiction ?","a":"<div class=\"notion-course\"><p>Le mésusage est défini comme toute conduite de consommation caractérisée par l'existence de <strong>risques</strong>, de <strong>dommages</strong> et/ou de <strong><span class=\"nc-red_bg\">dépendance</span></strong>. Il se situe sur un gradient allant du non-usage à la <span class=\"nc-red_bg\">dépendance</span>.</p></div>"},{"i":"46ac1322cba1","n":77,"o":"77-3","u":"Diagnostic positif","t":"Savoir diagnostiquer un mésusage : usage à risque, nocif et dépendance","q":"Quelle est la définition de l'usage nocif des médicaments psychotropes ?","a":"<div class=\"notion-course\"><p>L'usage nocif est caractérisé par l'existence de <strong>complications physiques ou psychiques avérées</strong>, et ce, <strong>en l'absence de critères de <span class=\"nc-red_bg\">dépendance</span></strong>. C'est un trouble lié à l'usage, mais pas une addiction.</p></div>"},{"i":"48248905b1d7","n":77,"o":"77-3","u":"Diagnostic positif","t":"Savoir diagnostiquer un mésusage : usage à risque, nocif et dépendance","q":"Selon la CIM-10, quels sont les critères diagnostiques de la dépendance aux médicaments psychotropes comme les benzodiazépines ?","a":"<div class=\"notion-course\"><p>Le diagnostic de <span class=\"nc-red_bg\">dépendance</span> selon la CIM-10 repose sur la présence simultanée d'au moins <strong>trois manifestations</strong> au cours de la dernière année parmi les suivantes :</p><ul><li>Désir compulsif de consommer (<strong>craving</strong>).</li><li>Difficultés à contrôler l'usage (quantité, durée).</li><li>Présence d'un <strong><span class=\"nc-red nc-bold\">syndrome de sevrage</span></strong>.</li><li>Preuve d'une <strong>tolérance</strong> (besoin d'augmenter les doses pour obtenir le même effet).</li><li>Abandon <span class=\"nc-green_bg nc-bold\">progressif</span> des autres intérêts.</li><li>Poursuite de la consommation malgré les conséquences nocives avérées (sociales, médicales).</li></ul></div>"},{"i":"dcf4cf828595","n":77,"o":"77-3","u":"Diagnostic positif","t":"Savoir diagnostiquer un mésusage : usage à risque, nocif et dépendance","q":"Qu'est-ce qu'un usage à risque des benzodiazépines et est-il considéré comme une maladie ?","a":"<div class=\"notion-course\"><p>Consommation exposant à un risque : dose, durée, association, terrain ou usage non prescrit inadaptés. Un risque seul ne démontre ni dommage constitué ni addiction.</p></div>"},{"i":"19a54d6ba2a7","n":77,"o":"77-4","u":"Diagnostic positif","t":"Savoir diagnostiquer un syndrome de sevrage et complications du sevrage","q":"Quels sont les facteurs augmentant le risque d'un syndrome de sevrage sévère aux benzodiazépines ?","a":"<div class=\"notion-course\"><ul><li>Une <strong>diminution rapide</strong> de la posologie.</li><li>Une <strong>posologie élevée</strong> de benzodiazépines.</li><li>Une benzodiazépine à <strong>demi-vie d'élimination courte</strong>.</li><li>Une <strong><span class=\"nc-blue_bg\">anxiété</span> importante</strong> préexistante ou à l'arrêt.</li><li>Un <strong>épisode dépressif caractérisé</strong> associé.</li><li>Une <strong>surconsommation d'alcool</strong> ou d'une autre substance psychoactive.</li></ul></div>"},{"i":"2706c87ec73f","n":77,"o":"77-4","u":"Diagnostic positif","t":"Savoir diagnostiquer un syndrome de sevrage et complications du sevrage","q":"Comment définit-on le syndrome de sevrage aux benzodiazépines ?","a":"<div class=\"notion-course\"><p>Le <span class=\"nc-red nc-bold\">syndrome de sevrage</span> aux benzodiazépines est l'apparition de <strong>signes nouveaux</strong> consécutifs à l'arrêt ou à la diminution de la consommation de benzodiazépines.</p></div>"},{"i":"3e2028a35c14","n":77,"o":"77-4","u":"Diagnostic positif","t":"Savoir diagnostiquer un syndrome de sevrage et complications du sevrage","q":"Quels sont les signes cliniques fréquents, spécifiques et graves d'un syndrome de sevrage aux benzodiazépines ?","a":"<div class=\"notion-course\"><p><span class=\"nc-blue_bg\">Anxiété</span>, <span class=\"nc-blue_bg\">insomnie</span>, <span class=\"nc-red nc-bold\">tremblements</span> et troubles perceptifs ; <span class=\"nc-yellow_bg\">confusion</span>/délirium et <span class=\"nc-red nc-bold\">convulsions</span> dans les formes graves. Aucun signe isolé n’est spécifique.</p></div>"},{"i":"dce7940ce2bb","n":77,"o":"77-4","u":"Diagnostic positif","t":"Savoir diagnostiquer un syndrome de sevrage et complications du sevrage","q":"Quel est le délai d'apparition des symptômes et quelle est la complication la plus grave du sevrage aux benzodiazépines ?","a":"<div class=\"notion-course\"><p>Délai variable selon la demi-vie et la baisse de dose, parfois retardé. Convulsions et délirium sont des urgences.</p></div>"},{"i":"0b2d39781f5d","n":77,"o":"77-7","u":"Prise en charge","t":"Connaître les modalités de prévention de la pharmacodépendance","q":"Quels principes guident une prescription anxiolytique ou hypnotique de BZD ?","a":"<div class=\"notion-course\"><p>Dose minimale, durée brève, pas de doublon, réévaluation et plan d’<span class=\"nc-green_bg nc-bold\">arrêt</span> ; éviter les associations sédatives.</p></div>"},{"i":"526fe822d02b","n":77,"o":"77-7","u":"Prise en charge","t":"Connaître les modalités de prévention de la pharmacodépendance","q":"Quelles sont les durées maximales de prescription des benzodiazépines selon leur indication, incluant la période de sevrage ?","a":"<div class=\"notion-course\"><ul><li>Pour un <strong><span class=\"nc-yellow_bg\">anxiolytique</span></strong> : <strong>≤ 12 <span class=\"nc-pink_bg\">semaines</span></strong>.</li><li>Pour un <strong>hypnotique</strong> : <strong><span class=\"nc-pink nc-bold\">≤ 4 semaines</span></strong>.</li></ul></div>"},{"i":"56cdd752c17d","n":77,"o":"77-7","u":"Prise en charge","t":"Connaître les modalités de prévention de la pharmacodépendance","q":"Quelles sont les spécificités de la prescription de benzodiazépines chez le sujet âgé (&ge; 65 ans) et pour le zolpidem ?","a":"<div class=\"notion-course\"><p>Sujet âgé : éviter si possible et adapter une faible dose au produit et au terrain. <span class=\"nc-pink nc-bold\">Zolpidem</span> : <span class=\"nc-yellow_bg\">ordonnance sécurisée</span>.</p></div>"},{"i":"9a8ee4d3deec","n":77,"o":"77-7","u":"Prise en charge","t":"Connaître les modalités de prévention de la pharmacodépendance","q":"Quel est le piège classique lié à l'arrêt d'une benzodiazépine, et comment doit être cette modalité d'arrêt ?","a":"<div class=\"notion-course\"><p>Un traitement prolongé ne doit pas être arrêté brutalement : <span class=\"nc-orange_bg\">risque de</span> sevrage, notamment convulsif. Prévoir une diminution adaptée.</p></div>"},{"i":"d682111e6945","n":77,"o":"77-7","u":"Prise en charge","t":"Connaître les modalités de prévention de la pharmacodépendance","q":"Comment doit être anticipée la prévention de la pharmacodépendance aux benzodiazépines dès la prescription initiale ?","a":"<div class=\"notion-course\"><p>Dès l'introduction d'une benzodiazépine, il faut <strong>prévoir son <span class=\"nc-green_bg nc-bold\">arrêt</span></strong>, <strong>s'interroger régulièrement sur la persistance de l'indication et de la posologie</strong>, et <strong>encadrer plus étroitement la prescription et la délivrance</strong>.</p></div>"},{"i":"fdd3a1259d02","n":77,"o":"77-7","u":"Prise en charge","t":"Connaître les modalités de prévention de la pharmacodépendance","q":"Quelles sont les autres modalités de prévention de la pharmacodépendance aux benzodiazépines, en complément des règles de prescription ?","a":"<div class=\"notion-course\"><p>Il est essentiel de fournir au patient une <strong>information et une éducation thérapeutique</strong>. Il faut également privilégier les <strong>alternatives non médicamenteuses</strong>, comme les prises en charge psychothérapeutiques, souvent plus efficaces qu'un traitement inadapté.</p></div>"},{"i":"221d4eed9c9b","n":77,"o":"77-5","u":"Diagnostic positif","t":"Savoir diagnostiquer les comorbidités psychiatriques et addictives","q":"Que rechercher avant de diminuer une BZD ?","a":"<div class=\"notion-course\"><ul><li>Trouble initial, <span class=\"nc-blue_bg\">anxiété</span>/dépression/suicide, sommeil, alcool/opioïdes, autres ordonnances, chutes et soutien.</li></ul></div>"},{"i":"750ab4dbcefd","n":77,"o":"77-6","u":"Epidémiologie","t":"Connaître l’épidémiologie de la dépendance aux benzodiazépines et apparentés","q":"Neuf millions d’utilisateurs de BZD signifie-t-il neuf millions d’addictions ?","a":"<div class=\"notion-course\"><ul><li>Non : ce chiffre ANSM 2024 porte sur les utilisateurs, pas sur le trouble de l’usage.</li></ul></div>"},{"i":"cb1b6ebc384a","n":77,"o":"77-8","u":"Prise en charge","t":"Connaître les principes de réduction des dommages et des risques","q":"Une baisse partielle des BZD peut-elle être un succès ?","a":"<div class=\"notion-course\"><ul><li>Oui : réduction des risques, objectifs partagés et maintien du suivi.</li></ul></div>"},{"i":"52bb335fc67b","n":77,"o":"77-9","u":"Prise en charge","t":"Connaître les modalités de la prise en charge du sevrage","q":"Existe-t-il une vitesse universelle de décroissance des BZD ?","a":"<div class=\"notion-course\"><ul><li>Non : paliers individualisés, sur <span class=\"nc-pink_bg\">semaines</span> à mois selon dose, durée et tolérance.</li></ul></div>"},{"i":"abd4ca6930a3","n":77,"o":"77-1","u":"Définition","t":"Connaître la définition de l’addiction aux benzodiazépines et apparentés","q":"Tolérance et sevrage sous prescription suffisent-ils à diagnostiquer une addiction ?","a":"<div class=\"notion-course\"><ul><li>Non : distinguer <span class=\"nc-red_bg\">dépendance</span> physique et trouble de l’usage, avec perte de contrôle et retentissement.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181d98572d394bc93953c?pvs=204","reviewedAt":"2026-10-14","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif.","sddStatus":"Situations LiSA vérifiées le 14 octobre 2026 dans la session UNESS connectée.","algorithms":2,"lisaSituations":[{"number":256,"title":"Prescrire un hypnotique/anxiolytique","url":"https://livret.uness.fr/lisa/2026/Prescrire_un_hypnotique/anxiolytique_SDD-256","expectations":["Préciser le trouble du sommeil, rechercher une apnée et privilégier les approches non médicamenteuses.","Adapter prescription et déprescription au terrain ; expliquer dépendance et sevrage, repérer mésusage et choisir l’ordonnance adaptée."],"verifiedAt":"2026-10-14"},{"number":340,"title":"Prise d’un toxique ou médicament potentiellement toxique","url":"https://livret.uness.fr/lisa/2026/Prise_volontaire_ou_involontaire_d%27un_toxique_ou_d%27un_m%C3%A9dicament_potentiellement_toxique_SDD-340","expectations":["Dater et quantifier l’exposition, reconnaître les toxidromes, évaluer la gravité et considérer un antidote adapté.","Organiser surveillance et orientation, évaluer intention suicidaire ou maltraitance et solliciter le centre antipoison selon la situation."],"verifiedAt":"2026-10-14"},{"number":292,"title":"Première consultation d’addictologie","url":"https://livret.uness.fr/lisa/2026/Premi%C3%A8re_consultation_d%27addictologie_SDD-292","expectations":["Caractériser usage nocif, dépendance ou addiction comportementale selon la classification utilisée ; rechercher sevrage, complications et comorbidités.","Évaluer les conséquences familiales, sociales et professionnelles, fixer des objectifs partagés et orienter ou proposer une substitution selon indication."],"verifiedAt":"2026-10-14"},{"number":293,"title":"Consultation de suivi addictologie","url":"https://livret.uness.fr/lisa/2026/Consultation_de_suivi_addictologie_SDD-293","expectations":["Rechercher manque, nouveaux symptômes, complications et comorbidités ; apprécier efficacité, tolérance et qualité de vie.","Adapter prescription et accompagnement social ; la valorisation du stage inclut psychothérapie, entretien motivationnel et soutien des proches avec respect de la confidentialité."],"verifiedAt":"2026-10-14"}]},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d94181d98572d394bc93953c?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf","label":"CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024) ↗"},{"href":"https://www.has-sante.fr/jcms/c_2038262/fr/arret-des-benzodiazepines-et-medicaments-apparentes-demarche-du-medecin-traitant-en-ambulatoire","label":"HAS · Arrêt des benzodiazépines, démarche en ambulatoire ↗"},{"href":"https://ansm.sante.fr/page/les-medicaments-et-moi-bub","label":"ANSM · Bon usage des benzodiazépines, données 2024 ↗"},{"href":"https://www.has-sante.fr/jcms/c_2863043/fr/quelle-place-pour-les-benzodiazepines-dans-l-anxiete","label":"HAS · Benzodiazépines dans l’anxiété ↗"},{"href":"https://www.has-sante.fr/jcms/c_2015058/fr/quelle-place-pour-les-benzodiazepines-dans-l-insomnie","label":"HAS · Benzodiazépines dans l’insomnie ↗"}]};
